function resolveAreaSpellCenter(world, actor, spell, intent) {
  const apos = /** @type any */ (world.get(actor, Position));
  if (!apos) return null;
  const actorFaction = String(world.get(actor, Faction)?.key || 'player');
  const range = Math.max(1, Number(spell?.range || 9) | 0);
  const isBlocked = createLOSBlocker(world);

  if (intent && intent.x != null && intent.y != null) {
    const ox = Number(intent.x) | 0;
    const oy = Number(intent.y) | 0;
    const dist = chebyshevScalar(ox, oy, apos.x | 0, apos.y | 0);
    if (!(dist > 0) || dist > range) {
      world.emit('spell:no-target', { actor, spellId: spell?.id || '', reason: 'out_of_range', range, requested: { x: ox, y: oy } });
      return null;
    }
    if (!hasSpellLineOfSight(world, {
      sourceId: actor,
      sourcePos: apos,
      targetPos: { x: ox, y: oy },
      range,
      isBlocked,
      allowFlyingOccupantAtTarget: true,
    })) {
      world.emit('spell:no-target', { actor, spellId: spell?.id || '', reason: 'blocked_los', range, requested: { x: ox, y: oy } });
      return null;
    }
    return { x: ox, y: oy, from: { x: apos.x | 0, y: apos.y | 0 } };
  }

  let bestId = 0;
  let bestD2 = Infinity;
  for (const [id, pos] of world.query(Position)) {
    if (id === actor) continue;
    const fac = /** @type any */ (world.get(id, Faction));
    if (!fac || !areFactionsHostile(actorFaction, fac.key)) continue;
    const vit = /** @type any */ (world.get(id, Vitality));
    if (!vit || (vit.hp | 0) <= 0) continue;
    const dx = (pos.x | 0) - (apos.x | 0);
    const dy = (pos.y | 0) - (apos.y | 0);
    const d2 = dx * dx + dy * dy;
    if (d2 > range * range || d2 >= bestD2) continue;
    if (!hasSpellLineOfSight(world, {
      sourceId: actor,
      targetId: id,
      sourcePos: apos,
      targetPos: pos,
      range,
      isBlocked,
    })) continue;
    bestId = id;
    bestD2 = d2;
  }
  if (!bestId) {
    world.emit('spell:no-target', { actor, spellId: spell?.id || '', range });
    return null;
  }
  const tpos = /** @type any */ (world.get(bestId, Position));
  return { x: tpos.x | 0, y: tpos.y | 0, from: { x: apos.x | 0, y: apos.y | 0 } };
}

function buildSolidPointSet(world, ignoreId = 0) {
  const blocked = new Set();
  for (const [id, pos] of world.query(Position)) {
    if (id === ignoreId) continue;
    const col = /** @type any */ (world.get(id, Collider));
    if (col && col.solid) blocked.add(`${pos.x | 0},${pos.y | 0}`);
  }
  return blocked;
}

function tryPullOneStep(pos, cx, cy, blocked) {
  const x = pos.x | 0;
  const y = pos.y | 0;
  const sx = Math.sign((cx | 0) - x);
  const sy = Math.sign((cy | 0) - y);
  if (sx === 0 && sy === 0) return false;
  const candidates = [];
  if (sx !== 0 && sy !== 0) candidates.push({ x: x + sx, y: y + sy });
  if (Math.abs((cx | 0) - x) >= Math.abs((cy | 0) - y)) {
    if (sx !== 0) candidates.push({ x: x + sx, y });
    if (sy !== 0) candidates.push({ x, y: y + sy });
  } else {
    if (sy !== 0) candidates.push({ x, y: y + sy });
    if (sx !== 0) candidates.push({ x: x + sx, y });
  }
  for (const next of candidates) {
    const key = `${next.x},${next.y}`;
    if (!isWalkable(next.x, next.y) || blocked.has(key)) continue;
    blocked.delete(`${x},${y}`);
    pos.x = next.x;
    pos.y = next.y;
    blocked.add(key);
    return true;
  }
  return false;
}

REGISTRY['void_hole'] = function voidHoleScript(world, actor, spell, intent) {
  const center = resolveAreaSpellCenter(world, actor, spell, intent);
  if (!center) return;
  const actorFaction = String(world.get(actor, Faction)?.key || 'player');
  const radius = resolveSpellRadius(world, actor, spell) || 3;
  const blocked = buildSolidPointSet(world, actor);
  const affected = [];

  forEachInRadius(world, center.x, center.y, radius, (id, pos) => {
    if (id === actor) return;
    const fac = /** @type any */ (world.get(id, Faction));
    if (!fac || !areFactionsHostile(actorFaction, fac.key)) return;
    const vit = /** @type any */ (world.get(id, Vitality));
    if (!vit || (vit.hp | 0) <= 0) return;
    const dx = (pos.x | 0) - center.x;
    const dy = (pos.y | 0) - center.y;
    const dist = Math.max(Math.abs(dx), Math.abs(dy));
    if (dist > radius) return;

    const before = { x: pos.x | 0, y: pos.y | 0 };
    const pullSteps = dist >= 3 ? 2 : 1;
    for (let step = 0; step < pullSteps; step++) {
      if (!tryPullOneStep(pos, center.x, center.y, blocked)) break;
    }
    affected.push({ id, from: before, to: { x: pos.x | 0, y: pos.y | 0 } });

    dealDamage(world, buildSpellDamageSpec(world, actor, id, {
      spell,
      baseAmount: dist <= 1 ? 5 : 4,
      type: 'shadow',
      cause: 'spell:void_hole',
      at: { x: pos.x | 0, y: pos.y | 0 },
      salt: 0x501d ^ id,
    }));
  });

  world.emit(new VoidHoleCast({
    actor,
    from: center.from,
    origin: { x: center.x, y: center.y },
    radius,
    affected,
  }));
};

