  const bracketColor = isEnemy
    ? `rgba(220,140,255,${(0.85 * pulse).toFixed(3)})`
    : `rgba(255,255,200,${(0.85 * pulse).toFixed(3)})`;

  bctx.strokeStyle = circleColor;
  bctx.lineWidth = 0.08;
